#pragma once

#include "gui_forms/binding/property_cell/property_cell.hpp"
#include "gui_forms/controls/range_control.hpp"

#include <cstdint>
#include <optional>
#include <string>
#include <utility>

namespace gui_forms {

// Dial's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/dial.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks), the
// compare and store, then the written hook (the touch, side effects and the
// change event, through the protected virtual on_<property>_changed() where
// Windows Forms has an overridable On<Property>Changed; other properties
// have no hook, and a subclass subscribes to their change events instead). A read is
// `(*control).x.read()`.

// Distance in value units between scale marks; zero draws none. Negative or not finite throws std::invalid_argument.
template <typename Declaring>
struct DialTickFrequencyCapability {
    PropertyCell<double, DialTickFrequencyCapability<Declaring>> tick_frequency{10.0};

    static void assign(DialTickFrequencyCapability& capability, double incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.tick_frequency), incoming);
        if (!capability.tick_frequency.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.tick_frequency));
    }
};

// Whether the scale lights the arc from the minimum to the value.
template <typename Declaring>
struct DialShowArcCapability {
    PropertyCell<bool, DialShowArcCapability<Declaring>> show_arc{true};

    static void assign(DialShowArcCapability& capability, bool incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.show_arc), incoming);
        if (!capability.show_arc.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.show_arc));
    }
};

// Every Dial capability, in the order the declaring class takes them.
template <typename Declaring>
struct DialCapabilities : public DialTickFrequencyCapability<Declaring>,
                          public DialShowArcCapability<Declaring> {};

} // namespace gui_forms
